import math

def count_odd_f_fixed(p, q, tie_breaker='x_inc', limit=100):
    max_M = p * (limit - 1) + q * (limit - 1)
    freq = [0] * (max_M + 1)
    for x in range(max_M // p + 1):
        for y in range((max_M - p*x) // q + 1):
            freq[p*x + q*y] += 1
    prefix_sum = [0] * (max_M + 2)
    for M in range(max_M + 1):
        prefix_sum[M+1] = prefix_sum[M] + freq[M]

    g = math.gcd(p, q)
    q_prime = q // g
    p_prime = p // g

    N = 0
    for x in range(limit):
        for y in range(limit):
            M = p*x + q*y
            rank = prefix_sum[M]
            if tie_breaker == 'x_inc':
                rank += x // q_prime
            else:
                rank += y // p_prime
            if rank % 2 == 1:
                N += 1
    return N

