import math

def count_odd_f_slow(p, q, tie_breaker='x_inc', limit=100):
    def floor_sum(n, m, a, b):
        ans = 0
        if a >= m:
            ans += (n - 1) * n * (a // m) // 2
            a %= m
        if b >= m:
            ans += n * (b // m)
            b %= m
        y_max = (a * n + b) // m
        if y_max == 0:
            return ans
        x_max = (y_max * m - b)
        ans += (n - (x_max + a - 1) // a) * y_max
        ans += floor_sum(y_max, a, m, (a - x_max % a) % a)
        return ans

    def get_rank(x, y, p, q, tie_breaker):
        M = p * x + q * y
        if M == 0:
            rank = 0
        else:
            n = (M - 1) // p + 1
            b = M - 1 - p * (n - 1)
            rank = floor_sum(n, q, p, b) + n

        g = math.gcd(p, q)
        if tie_breaker == 'x_inc':
            rank += x // (q // g)
        else:
            rank += y // (p // g)
        return rank

    N = 0
    for x in range(limit):
        for y in range(limit):
            if get_rank(x, y, p, q, tie_breaker) % 2 == 1:
                N += 1
    return N

